<?php

declare(strict_types=1);

namespace App\Modules\Catalog\UseCases;

use App\Modules\Catalog\DTOs\CategoryDTO;
use App\Modules\Catalog\Models\Category;
use App\Modules\Catalog\Repositories\CategoryRepository;
use Illuminate\Database\Eloquent\ModelNotFoundException;

/**
 * Admin: renames a category (the slug is regenerated by the model).
 */
final class UpdateCategoryUseCase
{
    public function __construct(private readonly CategoryRepository $categories) {}

    /**
     * @throws ModelNotFoundException
     */
    public function execute(string $categoryId, CategoryDTO $data): Category
    {
        $category = $this->categories->findOrFail($categoryId);

        return $this->categories->update($category, $data->toArray())->loadCount('products');
    }
}
